export enum DeviceKind { Sensor = "sensor", Gateway = "gateway", Display = "display" }
export enum DeviceState { Ready = "ready", Assigned = "assigned", Retired = "retired" }

export interface Device {
  id: string;
  ownerCode: string;
  label: string;
  kind: DeviceKind;
  state: DeviceState;
  unitCost: number;
  ports: number;
}

function validate(device: Device): void {
  if (![device.id, device.ownerCode, device.label].every(v => typeof v === "string" && v.trim().length > 0)) {
    throw new TypeError("text fields must be nonblank");
  }
  if (!Number.isFinite(device.unitCost) || device.unitCost < 0) throw new RangeError("invalid unitCost");
  if (!Number.isInteger(device.ports) || device.ports < 0) throw new RangeError("invalid ports");
  if (!Object.values(DeviceKind).includes(device.kind) || !Object.values(DeviceState).includes(device.state)) throw new TypeError("invalid enum value");
}

export class DeviceCatalog {
  private readonly devices = new Map<string, Device>();

  add(device: Device): void {
    validate(device);
    if (this.devices.has(device.id)) throw new Error("duplicate device id");
    this.devices.set(device.id, { ...device });
  }

  revise(id: string, patch: Omit<Partial<Device>, "id">): void {
    const current = this.devices.get(id);
    if (!current) throw new Error("unknown device id");
    const merged = { ...current, ...patch, id };
    validate(merged);
    this.devices.set(id, merged);
  }

  remove(id: string): boolean { return this.devices.delete(id); }

  find(id: string): Device | undefined {
    return this.devices.get(id);
  }

  list(): Device[] { return Array.from(this.devices.values(), device => ({ ...device })); }
}

