import { DeviceCatalog, DeviceKind, DeviceState } from './solution';
import type { Device } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, ctor: Function, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof (ctor as any)) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

function device(id: string, label = 'Sensor'): Device {
  return { id, ownerCode: 'OWN', label, kind: DeviceKind.Sensor, state: DeviceState.Ready, unitCost: 12.5, ports: 0 };
}

const catalog = new DeviceCatalog();
equal(catalog.list().length, 0, 'empty catalog');
const original = device('d1');
catalog.add(original);
original.label = 'caller mutation';
equal(catalog.find('d1')!.label, 'Sensor', 'add input copied');

const found = catalog.find('d1')!;
found.label = 'find mutation';
equal(catalog.find('d1')!.label, 'Sensor', 'find output copied');
assert(catalog.find('missing') === undefined, 'missing find');

catalog.add({ ...device('d2', 'Gateway'), kind: DeviceKind.Gateway, ports: 4 });
const listed = catalog.list();
equal(listed.length, 2, 'list size');
equal(listed[0].id, 'd1', 'insertion order first');
equal(listed[1].id, 'd2', 'insertion order second');
listed[0].label = 'list mutation';
listed.pop();
equal(catalog.list().length, 2, 'list array copied');
equal(catalog.find('d1')!.label, 'Sensor', 'list objects copied');

const patch = { label: 'Revised', unitCost: 20 };
catalog.revise('d1', patch);
patch.label = 'mutated patch';
equal(catalog.find('d1')!.label, 'Revised', 'patch copied');
equal(catalog.list()[0].id, 'd1', 'revision preserves position');
equal(catalog.find('d1')!.ownerCode, 'OWN', 'revision merges existing fields');

throws(() => catalog.add(device('d1')), Error, 'duplicate id');
throws(() => catalog.revise('absent', { label: 'x' }), Error, 'missing revision');
for (const field of ['id', 'ownerCode', 'label'] as const) {
  const bad = device(`bad-${field}`);
  bad[field] = ' \t ';
  throws(() => catalog.add(bad), TypeError, `blank ${field}`);
}
for (const cost of [-1, Infinity, -Infinity, NaN]) {
  throws(() => catalog.add({ ...device(`cost-${String(cost)}`), unitCost: cost }), RangeError, `invalid cost ${String(cost)}`);
}
for (const ports of [-1, 1.5, Infinity, NaN]) {
  throws(() => catalog.add({ ...device(`ports-${String(ports)}`), ports }), RangeError, `invalid ports ${String(ports)}`);
}
const beforeFailedRevision = catalog.find('d2')!;
throws(() => catalog.revise('d2', { ports: 2.5, label: 'should not commit' }), RangeError, 'invalid merged revision');
const afterFailedRevision = catalog.find('d2')!;
equal(afterFailedRevision.label, beforeFailedRevision.label, 'failed revision is atomic');
equal(afterFailedRevision.ports, beforeFailedRevision.ports, 'failed revision preserves ports');

equal(catalog.remove('missing'), false, 'remove missing');
equal(catalog.remove('d1'), true, 'remove existing');
assert(catalog.find('d1') === undefined, 'removed device absent');
equal(catalog.list()[0].id, 'd2', 'remaining order');

